-- GENERATED by benchmarks/tpch/scripts/qualify_queries.py from ../queries — do not edit.
-- Mixed layout: dimensions in postgresql.tpch_mixed, facts in hive.tpch.
-- TPC-H Q9: Product Type Profit Measure (simplified)
-- Uses multi-way join, LIKE, GROUP BY
SELECT
    n_name AS nation,
    SUM(l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity) AS sum_profit
FROM postgresql.tpch_mixed.part
JOIN hive.tpch.lineitem ON p_partkey = l_partkey
JOIN postgresql.tpch_mixed.partsupp ON l_suppkey = ps_suppkey AND l_partkey = ps_partkey
JOIN postgresql.tpch_mixed.supplier ON s_suppkey = l_suppkey
JOIN hive.tpch.orders ON o_orderkey = l_orderkey
JOIN postgresql.tpch_mixed.nation ON s_nationkey = n_nationkey
WHERE p_name LIKE '%green%'
GROUP BY n_name
ORDER BY n_name
